USE jac_lx_t200_20261020;
CREATE TABLE `_pristine_g_n_profile_d2a57d` LIKE `g_n_profile_d2a57d`;INSERT INTO `_pristine_g_n_profile_d2a57d` SELECT * FROM `g_n_profile_d2a57d`;
CREATE TABLE `_pristine_g_n_tweet_d2a57d` LIKE `g_n_tweet_d2a57d`;INSERT INTO `_pristine_g_n_tweet_d2a57d` SELECT * FROM `g_n_tweet_d2a57d`;
DELIMITER //
CREATE TRIGGER littlex_graph_insert AFTER INSERT ON anchors FOR EACH ROW BEGIN IF COALESCE(@wb_loading,0)=0 THEN
IF NEW.kind='NodeAnchor' AND NEW.arch_type='Profile' THEN INSERT INTO `g_n_profile_d2a57d`(`id`,`root_id`,`acl_all`,`acl_spec`,`frag`,`f_username`,`f_bio`,`f_created_at`) VALUES(NEW.id,NEW.root_id,COALESCE(CAST(JSON_UNQUOTE(JSON_EXTRACT(NEW.props,'$.access.all')) AS SIGNED),-1),(COALESCE(JSON_LENGTH(JSON_EXTRACT(NEW.props,'$.access.roots.anchors')),0)>0),JSON_SET(JSON_REMOVE(JSON_EXTRACT(NEW.props,'$.archetype'),'$.__type__','$.__module__'),'$._jac_type',NEW.arch_type,'$._jac_id',REPLACE(NEW.id,'-',''),'$._jac_archetype','node'),CAST(JSON_EXTRACT(NEW.props,'$.archetype.username') AS CHAR CHARACTER SET utf8mb4),CAST(JSON_EXTRACT(NEW.props,'$.archetype.bio') AS CHAR CHARACTER SET utf8mb4),CAST(JSON_EXTRACT(NEW.props,'$.archetype.created_at') AS CHAR CHARACTER SET utf8mb4)); END IF;
IF NEW.kind='NodeAnchor' AND NEW.arch_type='Tweet' THEN INSERT INTO `g_n_tweet_d2a57d`(`id`,`root_id`,`acl_all`,`acl_spec`,`frag`,`f_seed_id`,`f_content`,`f_author_username`,`f_created_at`,`f_likes`,`f_comments`) VALUES(NEW.id,NEW.root_id,COALESCE(CAST(JSON_UNQUOTE(JSON_EXTRACT(NEW.props,'$.access.all')) AS SIGNED),-1),(COALESCE(JSON_LENGTH(JSON_EXTRACT(NEW.props,'$.access.roots.anchors')),0)>0),JSON_SET(JSON_REMOVE(JSON_EXTRACT(NEW.props,'$.archetype'),'$.__type__','$.__module__'),'$._jac_type',NEW.arch_type,'$._jac_id',REPLACE(NEW.id,'-',''),'$._jac_archetype','node'),CAST(JSON_EXTRACT(NEW.props,'$.archetype.seed_id') AS CHAR CHARACTER SET utf8mb4),CAST(JSON_EXTRACT(NEW.props,'$.archetype.content') AS CHAR CHARACTER SET utf8mb4),CAST(JSON_EXTRACT(NEW.props,'$.archetype.author_username') AS CHAR CHARACTER SET utf8mb4),CAST(JSON_EXTRACT(NEW.props,'$.archetype.created_at') AS CHAR CHARACTER SET utf8mb4),CAST(JSON_EXTRACT(NEW.props,'$.archetype.likes') AS CHAR CHARACTER SET utf8mb4),CAST(JSON_EXTRACT(NEW.props,'$.archetype.comments') AS CHAR CHARACTER SET utf8mb4)); END IF;
END IF;END//
CREATE TRIGGER littlex_graph_update AFTER UPDATE ON anchors FOR EACH ROW BEGIN IF COALESCE(@wb_loading,0)=0 THEN
DELETE FROM `g_n_profile_d2a57d` WHERE id=OLD.id;
IF NEW.kind='NodeAnchor' AND NEW.arch_type='Profile' THEN INSERT INTO `g_n_profile_d2a57d`(`id`,`root_id`,`acl_all`,`acl_spec`,`frag`,`f_username`,`f_bio`,`f_created_at`) VALUES(NEW.id,NEW.root_id,COALESCE(CAST(JSON_UNQUOTE(JSON_EXTRACT(NEW.props,'$.access.all')) AS SIGNED),-1),(COALESCE(JSON_LENGTH(JSON_EXTRACT(NEW.props,'$.access.roots.anchors')),0)>0),JSON_SET(JSON_REMOVE(JSON_EXTRACT(NEW.props,'$.archetype'),'$.__type__','$.__module__'),'$._jac_type',NEW.arch_type,'$._jac_id',REPLACE(NEW.id,'-',''),'$._jac_archetype','node'),CAST(JSON_EXTRACT(NEW.props,'$.archetype.username') AS CHAR CHARACTER SET utf8mb4),CAST(JSON_EXTRACT(NEW.props,'$.archetype.bio') AS CHAR CHARACTER SET utf8mb4),CAST(JSON_EXTRACT(NEW.props,'$.archetype.created_at') AS CHAR CHARACTER SET utf8mb4)); END IF;
DELETE FROM `g_n_tweet_d2a57d` WHERE id=OLD.id;
IF NEW.kind='NodeAnchor' AND NEW.arch_type='Tweet' THEN INSERT INTO `g_n_tweet_d2a57d`(`id`,`root_id`,`acl_all`,`acl_spec`,`frag`,`f_seed_id`,`f_content`,`f_author_username`,`f_created_at`,`f_likes`,`f_comments`) VALUES(NEW.id,NEW.root_id,COALESCE(CAST(JSON_UNQUOTE(JSON_EXTRACT(NEW.props,'$.access.all')) AS SIGNED),-1),(COALESCE(JSON_LENGTH(JSON_EXTRACT(NEW.props,'$.access.roots.anchors')),0)>0),JSON_SET(JSON_REMOVE(JSON_EXTRACT(NEW.props,'$.archetype'),'$.__type__','$.__module__'),'$._jac_type',NEW.arch_type,'$._jac_id',REPLACE(NEW.id,'-',''),'$._jac_archetype','node'),CAST(JSON_EXTRACT(NEW.props,'$.archetype.seed_id') AS CHAR CHARACTER SET utf8mb4),CAST(JSON_EXTRACT(NEW.props,'$.archetype.content') AS CHAR CHARACTER SET utf8mb4),CAST(JSON_EXTRACT(NEW.props,'$.archetype.author_username') AS CHAR CHARACTER SET utf8mb4),CAST(JSON_EXTRACT(NEW.props,'$.archetype.created_at') AS CHAR CHARACTER SET utf8mb4),CAST(JSON_EXTRACT(NEW.props,'$.archetype.likes') AS CHAR CHARACTER SET utf8mb4),CAST(JSON_EXTRACT(NEW.props,'$.archetype.comments') AS CHAR CHARACTER SET utf8mb4)); END IF;
END IF;END//
CREATE TRIGGER littlex_graph_delete AFTER DELETE ON anchors FOR EACH ROW BEGIN IF COALESCE(@wb_loading,0)=0 THEN
DELETE FROM `g_n_profile_d2a57d` WHERE id=OLD.id;
DELETE FROM `g_n_tweet_d2a57d` WHERE id=OLD.id;
END IF;END//
DELIMITER ;
